mapper.update:
update logistics_bill_detail set register_status = #{status},
platform_order_no = #{platformOrderNo},
update_time = NOW(), track_time = NOW() from logistics_bill lb where lb.id = logistics_bill_detail.main_id and logistics_bill_detail.is_deleted = false and logistics_bill_detail.register_status != #{status} and lb.transport_no = #{transportNo}

mapper.select:
select lbd.id, lbd.track_no, lbd.platform_order_no, lb.carrier_id as carrierId, lb.tel_number as telNumber, lb.channel_id as channelId, lb.channel_name as channelName, lb.transport_no as transportNo, lb.sales_platform as salesPlatform, lb.shop_id as shopId, lc.track_query_type as trackQueryType from logistics_bill_detail lbd inner join logistics_bill lb on lbd.main_id = lb.id and lb.is_deleted = false LEFT JOIN logistics_channel lc on lb.channel_id = lc.id and lc.is_deleted = false where lbd.track_status not in('sign','manualComplete','systemComplete','deliveryFail') and (lbd.track_no != '' or lb.transport_no != '') and lbd.is_deleted = false -- and lbd.track_no != '' -- and lbd.track_time > CURRENT_DATE - INTERVAL '3 month'
and lb.order_type in ('B2B','B2C','AfterSale')
and lb.order_type = 'firstMile'
and (lc.track_query_mode = #{query.trackQueryMode} or lc.track_query_mode is NULL)
and lbd.register_status = #{query.registerStatus}
and lbd.track_enable = #{query.trackEnable}
and lbd.track_no in
#{item}
and lb.transport_no in
#{item}
